    return this.email;
  }
}

// Account has withdraw(), deposit(), freeze(); callers do: if (account.getBalance() < amount) { ... }
public class Account {
    private long balance;
    public long getBalance() {
        return this.balance;
    }
}

@dataclass(frozen=True)
class LineItem:
    quantity: int
    unit_price: Decimal

    @property
    def total(self) -> Decimal:
        return self.quantity * self.unit_price

func Mean(values []float64) float64 {
	sum := 0.0
	for _, v := range values {
		sum += v
	}
	return sum / float64(len(values))
}

shippingCost(order: Order): number {
  if (order.isExpress) {
    return this.expressCarrier.quote(order) + this.expressSurcharge(order);
  } else {
    return this.standardCarrier.quote(order);
  }
}

function parseBody(body: string | Buffer): Payload {
  if (typeof body === "string") {
    return JSON.parse(body);
  } else {
    return JSON.parse(body.toString("utf8"));
  }
}

public function activate(User $user): void
{
    if ($user === null) {
        throw new InvalidArgumentException("user required");
    }
    $this->repository->markActive($user);
}

public Receipt process(Order order) {
    Receipt receipt = new Receipt(order.id());
    ledger.open(order);
    if (order.total() > limit) {
        approvals.request(order);
    }
    ledger.close(order);
    return receipt;
}

private void approveIfLarge(Order order) {
    if (order.total() > limit) {
        approvals.request(order);
    }
}

function label(status: Status): string {
  switch (status) {
    case "open":
      return "Open";
    case "closed":
      return "Closed";
    default:
      return "Unknown";
  }
}

function label(status: "open" | "closed" | "held"): string {
  switch (status) {
    case "open":
      return "Open";
    case "closed":
      return "Closed";
    case "held":
      return "On hold";
  }
}

fn fee(tier: Tier) -> u32 {
    match tier {
        Tier::Free => 0,
        Tier::Pro => 900,
        Tier::Team => 2900,
    }
}

void apply(Event e) {
    switch (e.kind()) {
        case CREATED:
            index.add(e);
        case UPDATED:
            index.refresh(e);
            break;
        case DELETED:
            index.remove(e);
            break;
    }
}

void drain(FILE *in) {
    int c;
    while ((c = fgetc(in)) != EOF) {
        putchar(c);
    }
}

function next(queue) {
  if (queue.pop() !== undefined) {
    return queue.length;
  }
  return 0;
}

def allowed(self, user):
    if self.audit.log_access(user) and user.is_admin:
        return True
    return False

def allowed(self, user):
    if user.is_admin and not user.is_suspended:
        return True
    return False

@PostMapping("/orders")
public ResponseEntity<OrderView> create(@Valid @RequestBody CreateOrder body, Principal principal) {
    Order order = orders.place(body, principal.getName());
    return ResponseEntity.status(HttpStatus.CREATED).body(OrderView.of(order));
}

applyDiscount(code: string): void {
  const rule = this.rules.find(code);
  this.total = rule.apply(this.total);
}

